}

다음 코드를 수행할 때, 수행결과로 가장 적절한 것은?

int func(int& res, int val) {
res = res + val; return res;
}
void main() {
int sum = 0;
for(int a = 1; a < 4; a++) sum += func(sum, a); cout << sum << endl;
}

다음과 같은 SQL문을 연속적으로 실행하여 STUDENT 테이블을 생성한 다음, 2개의 투플을 삽입하고, CSTUDENT 뷰를 생성하였다. CSTUDENT 뷰에 데이터 를 삽입하는 SQL문 중 삽입이 되지 않는 것은?

CREATE TABLE STUDENT (SNO INT NOT NULL, NAME VARCHAR(10),
YEAR INT, DEPT VARCHAR(10), PRIMARY KEY (SNO) ); INSERT INTO STUDENT VALUES (1001, 'KIM', 4, 'COMPUTER'); INSERT INTO STUDENT VALUES (1002, 'LEE', 4, 'COMPUTER');
CREATE VIEW CSTUDENT (SNO, NAME, YEAR)
AS SELECT SNO, NAME, YEAR
FROM STUDENT WHERE DEPT = 'COMPUTER';
